const jobsBySessions = `-- name: JobsBySessions :many
select distinct on (session_id) id, org_id, owner_id, session_id, kind, state, goal, error, attempt, created_at, updated_at, started_at, stopped_at, cursor, check_command, verdict, check_proposed, assessment, model, max_duration_seconds, clock_started_at, clock_used_seconds, unfinished from jobs
where org_id = $1 and session_id = any($2::text[])
order by session_id, id desc
`

type JobsBySessionsParams struct {
	OrgID      string
	SessionIds []string
}

// The session list's decoration, in one query for the page rather than
// one per row. session_id is unique among a session's jobs (the
// composite foreign key), so `distinct on` returns at most one each;
// the id tie-break makes a corrupt store answer consistently rather
// than differently on each request.
//
// @decision(DL-060)
func (q *Queries) JobsBySessions(ctx context.Context, arg JobsBySessionsParams) ([]Job, error) {
	rows, err := q.db.Query(ctx, jobsBySessions, arg.OrgID, arg.SessionIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Job
	for rows.Next() {
		var i Job
		if err := rows.Scan(
			&i.ID,
			&i.OrgID,
			&i.OwnerID,
			&i.SessionID,
			&i.Kind,
			&i.State,
			&i.Goal,
			&i.Error,
			&i.Attempt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.StartedAt,
			&i.StoppedAt,
			&i.Cursor,
			&i.CheckCommand,
			&i.Verdict,
			&i.CheckProposed,
			&i.Assessment,
			&i.Model,
			&i.MaxDurationSeconds,
			&i.ClockStartedAt,
			&i.ClockUsedSeconds,
			&i.Unfinished,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

